from pathlib import Path
import pandas as pd,matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
OUT=Path(__file__).resolve().parent
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False})
x=pd.read_csv(OUT/'igar_label_agreement_by_app.csv').sort_values('disagreement_share')
fig,ax=plt.subplots(figsize=(9,4.8));bars=ax.barh(x.app,x.disagreement_share*100,color='#2c728e');ax.bar_label(bars,labels=[f'{v:.1f}%' for v in x.disagreement_share*100],padding=5);ax.set_xlim(0,60);ax.set_xlabel('Records with different rating-derived and source VADER labels (%)');ax.set_title('Labeling methods disagree on 41.3% of the same review records',loc='left',fontweight='bold',pad=18);fig.text(.08,.015,'IGAR auxiliary public-service apps, 2012–2023. Neither method is human ground truth. Not Auto2000 evidence.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.06,1,1]);fig.savefig(OUT/'igar_label_disagreement.png',dpi=180);plt.close(fig)
x=pd.read_csv(OUT/'province_charging_vs_registered_cars.csv').nlargest(10,'stations').sort_values('stations')
fig,(ax1,ax2)=plt.subplots(1,2,figsize=(11,5.5),sharey=True);bars=ax1.barh(x.province_name,x.stations,color='#2c728e');ax1.bar_label(bars,padding=3);ax1.set_xlim(0,580);ax1.set_xlabel('Consolidated station records');bars=ax2.barh(x.province_name,x.stations_per_100000_registered_passenger_vehicles,color='#718d54');ax2.bar_label(bars,labels=[f'{v:.1f}' for v in x.stations_per_100000_registered_passenger_vehicles],padding=3);ax2.set_xlim(0,26);ax2.set_xlabel('Sites per 100,000 registered passenger vehicles');fig.suptitle('Charging counts and vehicle-normalized context answer different questions',fontweight='bold',x=.04,ha='left');fig.text(.04,.015,'Charging snapshot: 16 Jun 2026, Wiputra & Santiadi V2 (CC BY-NC 3.0). Denominator: BPS/Polri 2025 all registered passenger cars.\nNot BEV demand, live capacity or uptime. East Java source stock discontinuity and station coordinate conflicts require caution.',fontsize=8,color='#555555');fig.tight_layout(rect=[0,.09,1,.95]);fig.savefig(OUT/'charging_count_vs_vehicle_context.png',dpi=180);plt.close(fig)
